'use strict';
// Browser-only inspection state. Native persistence, workers and Gmail evidence need backend integration.
const priceChanges=new Map();let pendingTrackingRemoval=null,trackingUndoTimer=null,detailReturnContext=null;
const priceHistoryExamples=[{id:'price-netflix-sep',recordId:'netflix-primary',oldPrice:'13.99',newPrice:'15.99',oldCurrency:'USD',newCurrency:'USD',oldCycle:'Monthly',newCycle:'Monthly',effectiveDate:'2026-09-27',recordedAt:'2026-09-27',reason:'change',source:'Updated by you'},{id:'price-netflix-jun',recordId:'netflix-primary',oldPrice:'11.99',newPrice:'13.99',oldCurrency:'USD',newCurrency:'USD',oldCycle:'Monthly',newCycle:'Monthly',effectiveDate:'2026-06-27',recordedAt:'2026-06-27',reason:'change',source:'Found in Gmail'}];
function detailPriceHistory(record){return [...priceHistoryExamples.filter(r=>r.recordId===record.id),...(priceChanges.get(record.id)||[])].sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate)||String(b.recordedAt).localeCompare(String(a.recordedAt)));}
function detailAnnualCost(record){if(record.price==null||String(record.price).trim()==='')return null;const factor={Monthly:12,Quarterly:4,Yearly:1,Weekly:52}[record.cycle];return factor&&Number.isFinite(Number(record.price))&&Number(record.price)>=0?Number(record.price)*factor:null;}
function detailSuccessfulReceipts(record){return detailReceiptRows(record).filter(r=>r.source==='Gmail receipt'&&r.evidenceId&&r.paidDate<=calendarToday);}
function detailSpendingCard(record){const receipts=detailSuccessfulReceipts(record),totals=paymentHistoryTotals(receipts),annual=detailAnnualCost(record),inactive=['Cancelled','Expired'].includes(record.status);return `<section class="panel detail-spending"><div class="spend-heading"><h3>Your spending</h3><button class="detail-inline-link" data-detail-payments="${escape(record.id)}">View payments ›</button></div><span class="note">Total recorded payments</span><strong class="detail-recorded-total">${totals.length?totals.map(r=>escape(r.currency)+' '+r.amount).join('<br>'):'No receipts yet'}</strong><p class="note">${receipts.length} payment${receipts.length===1?'':'s'} found · Available Gmail receipts only</p>${fr('Subscription since',record.start?detailDate(record.start):'Not set')}${record.createdAt?fr('Tracked since',detailDate(record.createdAt.slice(0,10))):''}${annual!==null?fr((inactive?'Last price':record.trial?'After trial':'Current price')+' · annual equivalent',escape(record.currency)+' '+annual.toFixed(2)+' estimated'):''}<p class="note">Recorded history may be incomplete. Estimates aren’t payments.</p></section>`;}
function priceAmount(amount,currency,cycle){return `${escape(currency)} ${Number(amount).toFixed(2)} · ${escape(cycle)}`;}
function detailPriceHistoryEntry(record){const latest=detailPriceHistory(record)[0];return `<button class="detail-related-link" data-open-price-history><span>Price history<small>${latest?priceAmount(latest.oldPrice,latest.oldCurrency,latest.oldCycle)+' → '+priceAmount(latest.newPrice,latest.newCurrency,latest.newCycle):'No price changes recorded'}</small></span><span aria-hidden="true">›</span></button>`;}
function priceHistoryScreen(){const record=currentDetailRecord(),rows=current==='Price history · empty'?[]:detailPriceHistory(record);return `<div class="head">${backButton({attributes:'data-price-history-back'})}<h2>Price history</h2></div><section class="panel price-current"><span class="avatar">${platformLogo(record.name)}</span><div><h3>${escape(record.name)}</h3><p class="note">Current tracked price</p><strong>${priceAmount(record.price,record.currency,record.cycle)}</strong></div></section>${rows.length?`<div class="price-timeline">${rows.map(row=>`<section class="panel price-change-row"><div class="spend-heading"><strong>${row.reason==='correction'?'Price corrected':'Price changed'}</strong><span class="detail-source">${escape(row.source)}</span></div><p>${priceAmount(row.oldPrice,row.oldCurrency,row.oldCycle)}<span aria-hidden="true"> → </span><strong>${priceAmount(row.newPrice,row.newCurrency,row.newCycle)}</strong></p>${fr(row.reason==='correction'?'Corrected on':'Effective from',detailDate(row.effectiveDate))}</section>`).join('')}</div><p class="note">Price changes don’t alter your previous payment receipts.</p>`:`<div class="price-history-empty">${mascotView({expression:'neutral',size:108,artworkScale:1.05})}<h3>No price changes yet</h3><p class="note">Changes appear here when you update a price or Gmail finds a verified change.</p></div>`}`;}
function detailValidDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const date=new Date(value+'T00:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(0,10)===value;}
function detailCancellationErrors(values,today=calendarToday){const errors={};if(!detailValidDate(values.cancelledAt)||values.cancelledAt>today)errors.cancelledAt='Choose today or a past cancellation date.';if(values.accessUntil&&(!detailValidDate(values.accessUntil)||values.accessUntil<values.cancelledAt))errors.accessUntil='Access must end on or after cancellation.';return errors;}
function cancelledTrackingRecord(record,values){return {...record,status:'Cancelled',cancelledAt:values.cancelledAt,accessUntil:values.accessUntil||'',accessEndReminder:!!values.accessEndReminder&&!!values.accessUntil&&values.accessUntil>=calendarToday};}
function closeDetailDialog(){const overlay=document.querySelector('.detail-dialog-overlay');if(!overlay)return;const phone=overlay.closest('.phone'),trigger=phone.querySelector('[data-mark-cancelled]');overlay.remove();phone.querySelectorAll('[data-detail-dialog-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-detail-dialog-inert');});trigger?.focus({preventScroll:true});}
function openCancellationSheet(trigger){const phone=trigger.closest('.phone'),record=currentDetailRecord(),overlay=document.createElement('div');overlay.className='detail-dialog-overlay';overlay.innerHTML=`<div class="track-again-shade" data-close-detail-dialog></div><section class="track-again-sheet cancellation-sheet" role="dialog" aria-modal="true" aria-labelledby="cancel-title"><div class="handle"></div><header><div><h3 id="cancel-title">Mark ${escape(record.name)} as cancelled?</h3><p>Record your cancellation details.</p></div><button data-close-detail-dialog aria-label="Close cancellation">×</button></header><form data-confirm-cancellation novalidate><label>Cancellation date<input name="cancelledAt" type="date" max="${calendarToday}" value="${calendarToday}" aria-describedby="cancel-date-error"><span class="manual-error" id="cancel-date-error" hidden></span></label><label>Access until <small>Optional</small><input name="accessUntil" type="date" min="${calendarToday}" aria-describedby="access-date-error"><span class="manual-error" id="access-date-error" hidden></span></label><label class="access-reminder-option" hidden><input name="accessEndReminder" type="checkbox"><span>Remind me when access ends</span></label><p class="track-again-note">This updates your tracking in Renewless. Cancel your plan on ${escape(record.name)} separately.</p><div class="detail-confirm-buttons"><button type="button" class="secondary" data-close-detail-dialog>Go back</button><button class="primary">Confirm cancellation</button></div></form></section>`;for(const child of phone.children)if(!child.inert){child.inert=true;child.dataset.detailDialogInert='true';}phone.append(overlay);overlay.querySelector('[data-close-detail-dialog]').focus();}
function deleteTrackingScreen(){const record=currentDetailRecord();return heading('Subscription',true)+`<div class="overlay" data-delete-shade><section class="sheet tracking-delete-sheet" role="dialog" aria-modal="true" aria-labelledby="delete-tracking-title"><h3 id="delete-tracking-title">Remove ${escape(record.name)} from Renewless?</h3><p>This removes its tracking and stops future reminders. Your ${escape(record.name)} subscription won’t be cancelled.</p><p class="note">Recorded payment history stays available.</p><div class="detail-confirm-buttons"><button class="secondary" data-cancel-delete>Go back</button>${action('Remove tracking','delete','primary')}</div></section></div>`;}
function removeTrackingAndOfferUndo(){const record={...currentDetailRecord()},hadOverride=trialRecords.has(record.id),override=trialRecords.get(record.id),reminder=reminderPreferences.get(record.id);clearTimeout(trackingUndoTimer);pendingTrackingRemoval={record,hadOverride,override,reminder,expiresAt:Date.now()+8000};trialRecords.set(record.id,{...record,status:'Deleted',accessEndReminder:false});reminderPreferences.delete(record.id);go('List');trackingUndoTimer=setTimeout(()=>{pendingTrackingRemoval=null;document.querySelectorAll('.tracking-undo').forEach(el=>el.remove());},8000);}
function renderTrackingUndo(){if(!pendingTrackingRemoval||!current.startsWith('List'))return;const phone=document.querySelector('#upgraded'),bar=document.createElement('div');bar.className='tracking-undo';bar.setAttribute('role','status');bar.innerHTML='<span>Tracking removed</span><button data-undo-tracking>Undo</button>';phone.append(bar);}
function undoTrackingRemoval(){if(!pendingTrackingRemoval)return;if(Date.now()>=pendingTrackingRemoval.expiresAt){pendingTrackingRemoval=null;document.querySelectorAll('.tracking-undo').forEach(el=>el.remove());toast('Undo is no longer available.');return;}const {record,hadOverride,override,reminder}=pendingTrackingRemoval;clearTimeout(trackingUndoTimer);if(hadOverride)trialRecords.set(record.id,override);else trialRecords.delete(record.id);if(reminder)reminderPreferences.set(record.id,reminder);state.manual=record;demoName=record.name;demoPrice=record.price;pendingTrackingRemoval=null;go('Detail');toast('Tracking restored.');}
function initPriceEditForm(){if(current!=='Edit')return;const form=document.querySelector('#upgraded .manual-form');if(!form)return;form.dataset.priceOriginal=JSON.stringify({...currentDetailRecord(),price:form.elements.price.value,currency:form.elements.currency.value,cycle:form.elements.cycle.value});const section=document.createElement('div');section.className='price-update-fields';section.hidden=true;section.innerHTML=`${selectField({label:'Reason for price update',name:'priceChangeType',value:'',options:[{value:'',label:'Choose an option'},{value:'change',label:'Price changed'},{value:'correction',label:'Correcting a mistake'}]})}<span class="manual-error" data-price-reason-error role="alert" hidden></span><label data-price-effective-label>Effective from<input name="priceEffectiveDate" type="date" max="${calendarToday}" value="${calendarToday}"><span class="manual-error" data-price-date-error role="alert" hidden></span></label><p class="note">Previous payment receipts stay unchanged.</p>`;form.querySelector('.manual-price-row').after(section);}
function priceEditChanged(form){const original=JSON.parse(form.dataset.priceOriginal||'{}');return Number(form.elements.price.value)!==Number(original.price)||form.elements.currency.value!==(original.currency||'USD')||form.elements.cycle.value!==(original.cycle||'Monthly');}
function syncPriceEdit(form){const section=form.querySelector('.price-update-fields');if(!section)return;section.hidden=!priceEditChanged(form);section.querySelector('[data-price-effective-label]').hidden=form.elements.priceChangeType.value==='correction';}
function validatePriceEdit(form){if(form.dataset.edit!=='true'||!priceEditChanged(form))return true;syncPriceEdit(form);const reason=form.elements.priceChangeType.value,date=form.elements.priceEffectiveDate.value;form.querySelector('[data-price-reason-error]').hidden=!!reason;form.querySelector('[data-price-reason-error]').textContent=reason?'':'Choose whether the price changed or you are correcting a mistake.';form.querySelector('.price-update-fields [data-select-trigger]').setAttribute('aria-invalid',String(!reason));const validDate=reason==='correction'||detailValidDate(date)&&date<=calendarToday;form.elements.priceEffectiveDate.setAttribute('aria-invalid',String(!validDate));form.querySelector('[data-price-date-error]').hidden=validDate;form.querySelector('[data-price-date-error]').textContent=validDate?'':'Choose today or a past effective date.';if(!reason)form.querySelector('.price-update-fields [data-select-trigger]').focus();else if(!validDate)form.elements.priceEffectiveDate.focus();return !!reason&&validDate;}
function priceHistoryEntry(old,record,reason,effectiveDate,recordedAt=new Date().toISOString()){return {id:'price-'+Date.now(),recordId:record.id,oldPrice:old.price,newPrice:record.price,oldCurrency:old.currency||'USD',newCurrency:record.currency,oldCycle:old.cycle||'Monthly',newCycle:record.cycle,effectiveDate:reason==='correction'?calendarToday:effectiveDate,recordedAt,reason,source:'Updated by you'};}
function storePriceEdit(form,record){if(form.dataset.edit!=='true'||!priceEditChanged(form))return;const old=JSON.parse(form.dataset.priceOriginal),row=priceHistoryEntry(old,record,form.elements.priceChangeType.value,form.elements.priceEffectiveDate.value);priceChanges.set(record.id,[...(priceChanges.get(record.id)||[]),row]);}

function resetDetailEnhancements(){priceChanges.clear();pendingTrackingRemoval=null;detailReturnContext=null;clearTimeout(trackingUndoTimer);}
function detailEnhancementsAfterRender(){if(isPostAuthHeaderScope(current)&&!current.startsWith('Home')){const label=document.querySelector('[data-variant=upgraded] .variant-title small');if(label)label.textContent='Final design · locked';}initPriceEditForm();renderTrackingUndo();if(current==='Delete confirm'){document.querySelector('#upgraded .head').inert=true;document.querySelector('#upgraded .tracking-delete-sheet button').focus();}if(current.startsWith('Detail')||current.startsWith('Price history')||current==='Delete confirm'||current==='Edit'){const label=document.querySelector('[data-variant=upgraded] .variant-title small');if(label)label.textContent='Final design · locked';}}
document.addEventListener('click',event=>{const cancel=event.target.closest('[data-mark-cancelled]');if(cancel)openCancellationSheet(cancel);else if(event.target.closest('[data-close-detail-dialog]'))closeDetailDialog();else if(event.target.closest('[data-price-edit-back]')){if(detailReturnContext?.id===currentDetailRecord().id)returnToDetail();else go('back');}else if(event.target.closest('[data-price-history-back], [data-cancel-delete]'))returnToDetail();else if(event.target.closest('[data-open-price-history]')){captureDetailReturnContext();state.manual={...currentDetailRecord()};go('Price history');}else if(event.target.closest('[data-undo-tracking]'))undoTrackingRemoval();});
for(const type of ['input','change'])document.addEventListener(type,event=>{const form=event.target.closest('.manual-form');if(form?.dataset.edit==='true')syncPriceEdit(form);const cancelForm=event.target.closest('[data-confirm-cancellation]');if(cancelForm){const date=cancelForm.elements.accessUntil.value,eligible=detailValidDate(date)&&date>=calendarToday;cancelForm.querySelector('.access-reminder-option').hidden=!eligible;if(!eligible)cancelForm.elements.accessEndReminder.checked=false;cancelForm.elements.accessUntil.min=cancelForm.elements.cancelledAt.value;}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-confirm-cancellation]');if(!form)return;event.preventDefault();const values={cancelledAt:form.elements.cancelledAt.value,accessUntil:form.elements.accessUntil.value,accessEndReminder:form.elements.accessEndReminder.checked},errors=detailCancellationErrors(values);for(const [field,id]of [['cancelledAt','cancel-date-error'],['accessUntil','access-date-error']]){form.querySelector('#'+id).textContent=errors[field]||'';form.querySelector('#'+id).hidden=!errors[field];form.elements[field].setAttribute('aria-invalid',String(!!errors[field]));}if(Object.keys(errors).length){form.elements[Object.keys(errors)[0]].focus();return;}const back=previous,record=cancelledTrackingRecord(currentDetailRecord(),values);trialRecords.set(record.id,record);reminderPreferences.delete(record.id);state.manual=record;closeDetailDialog();go('Detail');previous=back;toast('Cancellation recorded.');});
document.addEventListener('keydown',event=>{if(event.defaultPrevented)return;const overlay=document.querySelector('.detail-dialog-overlay')||(current==='Delete confirm'?document.querySelector('.tracking-delete-sheet'):null);if(!overlay)return;if(current==='Delete confirm'&&event.key==='Escape'){event.preventDefault();returnToDetail();document.querySelector('#upgraded .delete-icon')?.focus();return;}if(event.key==='Escape'){event.preventDefault();closeDetailDialog();}else if(event.key==='Tab'){const controls=[...overlay.querySelectorAll('button,input')].filter(el=>!el.closest('[hidden]')),first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

function manualFormValues(form){const values=Object.fromEntries(new FormData(form));delete values.priceChangeType;delete values.priceEffectiveDate;return values;}
function isPostAuthHeaderScope(name){return !groups.Auth.includes(name)&&!onboardingScreens.includes(name)&&!['Calendar','Add sheet','Widgets'].includes(name);}
document.addEventListener('click',event=>{if(current==='Delete confirm'&&event.target.matches('[data-delete-shade]'))returnToDetail();if(current.startsWith('Detail')&&event.target.closest('[data-go="Delete confirm"], [data-go="Edit"]'))captureDetailReturnContext();});

function captureDetailReturnContext(){detailReturnContext={id:currentDetailRecord().id,variant:current,back:previous,scroll:document.querySelector('#upgraded .content')?.scrollTop||0};}
function restoreDetailReturnContext(focus=true){const context=detailReturnContext?.id===currentDetailRecord().id?detailReturnContext:null;previous=context?.back||'List';const content=document.querySelector('#upgraded .content');if(content){content.scrollTop=context?.scroll||0;if(focus)content.querySelector('[data-open-price-history]')?.focus({preventScroll:true});}}
function returnToDetail(){const variant=detailReturnContext?.id===currentDetailRecord().id?detailReturnContext.variant:'Detail';go(variant);restoreDetailReturnContext();}
